function demoMain(idx,label){
  var fns=[["add","(a,b)","a+b"],["isEven","(n)","n%2===0"],["shout","(s)","s.toUpperCase()"]];
  var f=fns[idx%fns.length];
  var test="test('"+f[0]+" works',()=>{expect("+f[0]+f[1]+").toBeDefined();});";
  return "["+label+"] generated test for "+f[0]+f[1]+": "+test;
}

